/**
 * Class Routine.
 *
 * The same timetable seen two ways: by class (what a student attends) and by
 * teacher (what a staff member teaches). The teacher view is generated by
 * inverting every class routine, which is also how clashes would surface.
 */

import {
  html, icon, card, table, badge, emptyState, seriesColor, downloadFile, toCsv, toast,
} from '../core/ui.js';
import * as auth from '../core/auth.js';
import * as clock from '../core/clock.js';
import { routineFor, teacherRoutine, allStaff, staffById, studentById, classTeacherFor } from '../core/data.js';
import { CLASS_LIST, WEEKDAYS, PERIODS, subjectsFor } from '../core/spec.js';
import { fmtDate } from '../core/domain.js';

const state = { view: 'class', classKey: CLASS_LIST[0].key, staffId: null };

/** The routine a Student or Parent persona should see by default. */
function personaClassKey() {
  const children = auth.linkedChildren();
  return children[0]?.classKey || null;
}

function controls() {
  const teachers = allStaff().filter((s) => s.roles.includes('TEACHER'));
  const canPickView = !['STUDENT', 'PARENT'].includes(auth.currentRole());

  return html`
    <div class="row wrap" style="gap:9px">
      ${canPickView ? html`
        <select class="select" id="r-view" style="width:auto">
          <option value="class" ${state.view === 'class' ? 'selected' : ''}>By class</option>
          <option value="teacher" ${state.view === 'teacher' ? 'selected' : ''}>By teacher</option>
        </select>` : ''}
      ${state.view === 'class' ? html`
        <select class="select" id="r-class" style="width:auto">
          ${CLASS_LIST.map((c) => html`<option value="${c.key}" ${c.key === state.classKey ? 'selected' : ''}>${c.gradeName} — ${c.sectionName}</option>`)}
        </select>`
        : html`
        <select class="select" id="r-staff" style="width:auto">
          ${teachers.map((s) => html`<option value="${s.id}" ${s.id === state.staffId ? 'selected' : ''}>${s.name} — ${s.subject}</option>`)}
        </select>`}
      <button class="btn btn-sm" id="r-print">${icon('printer')} Print</button>
    </div>`;
}

// ---------------------------------------------------------------------------
// Class view
// ---------------------------------------------------------------------------

function classView() {
  const cls = CLASS_LIST.find((c) => c.key === state.classKey) || CLASS_LIST[0];
  const routine = routineFor(cls.key);
  const teacher = classTeacherFor(cls.key);
  const subjects = subjectsFor(cls.gradeId, cls.groupId);
  const todayIdx = clock.today().getDay();

  // Weekly period count per subject — the check that the timetable is balanced.
  const counts = {};
  for (const day of routine) for (const p of day.periods) counts[p.subject.code] = (counts[p.subject.code] || 0) + 1;

  return html`
    ${card({
      title: `${cls.gradeName} — ${cls.sectionName}`,
      sub: html`Class teacher: <strong>${teacher.name}</strong> · Sunday to Thursday · ${PERIODS.filter((p) => !p.isBreak).length} periods a day`,
      body: html`
        <div class="table-wrap">
          <table class="routine-grid">
            <thead>
              <tr>
                <th style="width:78px"></th>
                ${PERIODS.map((p) => html`
                  <th>${p.isBreak ? 'Break' : `${p.label} period`}<div class="xsmall muted mono">${p.start}</div></th>`)}
              </tr>
            </thead>
            <tbody>
              ${routine.map((day, di) => html`
                <tr>
                  <th style="text-align:left;vertical-align:middle">
                    ${day.day.slice(0, 3)}
                    ${di === todayIdx ? badge('today', 'brand') : ''}
                  </th>
                  ${PERIODS.map((slot) => {
                    if (slot.isBreak) return html`<td class="routine-cell brk"><span class="xsmall">Break</span></td>`;
                    const p = day.periods.find((x) => x.period === slot.id);
                    if (!p) return html`<td class="routine-cell"></td>`;
                    return html`
                      <td class="routine-cell" style="border-left:3px solid ${seriesColor(subjects.findIndex((s) => s.code === p.subject.code))}">
                        <div class="routine-sub">${p.subject.name}</div>
                        <div class="routine-meta">${p.teacher.name}</div>
                        <div class="routine-meta mono">Room ${p.room}</div>
                      </td>`;
                  })}
                </tr>`)}
            </tbody>
          </table>
        </div>`,
      foot: html`
        <div class="row wrap" style="gap:14px">
          ${Object.entries(counts).sort((a, b) => b[1] - a[1]).map(([code, n]) => html`
            <span class="xsmall"><strong>${code}</strong> ${n}×</span>`)}
          <span class="muted xsmall" style="margin-left:auto">Weekly period count per subject</span>
        </div>`,
    })}`;
}

// ---------------------------------------------------------------------------
// Teacher view
// ---------------------------------------------------------------------------

function teacherView() {
  const teachers = allStaff().filter((s) => s.roles.includes('TEACHER'));
  const staff = staffById(state.staffId) || teachers[0];
  state.staffId = staff.id;
  const week = teacherRoutine(staff.id);
  const load = week.reduce((s, d) => s + d.periods.length, 0);
  const todayIdx = clock.today().getDay();

  return html`
    <div class="grid g-4 mb-3">
      <div class="stat"><div class="stat-label">Weekly periods</div><div class="stat-value">${load}</div>
        <div class="stat-meta">${(load / 5).toFixed(1)} per working day</div></div>
      <div class="stat"><div class="stat-label">Designation</div><div class="stat-value sm">${staff.designation}</div>
        <div class="stat-meta">${staff.department} section</div></div>
      <div class="stat"><div class="stat-label">Main subject</div><div class="stat-value sm">${staff.subject}</div></div>
      <div class="stat"><div class="stat-label">Classes taught</div>
        <div class="stat-value">${new Set(week.flatMap((d) => d.periods.map((p) => p.classKey))).size}</div></div>
    </div>

    ${card({
      title: staff.name,
      sub: `${staff.designation} · joined ${fmtDate(staff.joinedOn, 'short')} · ${staff.yearsOfService} years of service`,
      flush: true,
      body: html`
        ${week.map((day, di) => html`
          <div style="border-bottom:1px solid var(--line)">
            <div class="row" style="padding:9px 15px;background:var(--surface-2);gap:8px">
              <strong>${day.day}</strong>
              ${di === todayIdx ? badge('today', 'brand') : ''}
              <span class="muted xsmall" style="margin-left:auto">${day.periods.length} period${day.periods.length === 1 ? '' : 's'}</span>
            </div>
            ${day.periods.length
              ? table(day.periods, [
                  { key: 'time', label: 'Time', render: (p) => html`<span class="mono">${p.start}–${p.end}</span>` },
                  { key: 'class', label: 'Class', render: (p) => html`<a href="#/students?class=${p.classKey}" style="color:inherit"><strong>${p.className}</strong></a>` },
                  { key: 'subject', label: 'Subject', render: (p) => p.subject.name },
                  { key: 'room', label: 'Room', align: 'center', render: (p) => html`<span class="mono">${p.room}</span>` },
                  {
                    key: 'act', label: '', align: 'right',
                    render: (p) => html`<a class="btn btn-sm" href="#/attendance?class=${p.classKey}">Attendance</a>`,
                  },
                ], { compact: true })
              : html`<div class="card-body"><span class="muted small">Free day — no periods scheduled.</span></div>`}
          </div>`)}`,
    })}`;
}

// ---------------------------------------------------------------------------
// Screen
// ---------------------------------------------------------------------------

export default {
  id: 'routine',
  title: 'Class Routine',
  module: 'routine',

  render(ctx) {
    // Students and parents get their own class, not a picker over all 56.
    const personaKey = personaClassKey();
    if (personaKey && ['STUDENT', 'PARENT'].includes(auth.currentRole())) {
      state.view = 'class';
      state.classKey = ctx.query.class || personaKey;
    } else if (auth.currentRole() === 'TEACHER' && !state.staffId) {
      state.view = 'teacher';
      state.staffId = auth.currentIdentity().staffId;
    }
    if (ctx.query.class && CLASS_LIST.some((c) => c.key === ctx.query.class)) state.classKey = ctx.query.class;

    return {
      title: 'Class Routine',
      sub: 'The weekly timetable, by class or by teacher. Both are views of one schedule.',
      actions: controls(),
      body: state.view === 'teacher' ? teacherView() : classView(),
    };
  },

  mount(root) {
    root.querySelector('#r-view')?.addEventListener('change', (e) => {
      state.view = e.target.value;
      window.ERP.repaint();
    });
    root.querySelector('#r-class')?.addEventListener('change', (e) => {
      state.classKey = e.target.value;
      window.ERP.repaint();
    });
    root.querySelector('#r-staff')?.addEventListener('change', (e) => {
      state.staffId = e.target.value;
      window.ERP.repaint();
    });
    root.querySelector('#r-print')?.addEventListener('click', () => window.print());
  },
};
